export const DATA_93: ReadingTest[] = [
  { id: "rd-159", num: 159, title: "Đề 159", timeMin: 60, parts: [
    { title: "Asia's Famous Streets: Between Commerce and Memory", paragraphs: ["Walk down certain streets in Bangkok, Hanoi, or Kolkata, and you can feel two different time periods pressing against each other at once. Neon signs for mobile phone shops hang above buildings that have stood for over a century. Motorbikes weave past vendors selling the same snacks their grandparents once sold on the same corner. These streets are rarely quiet, and they are rarely simple; each one carries decades of trade, migration, and daily life layered on top of one another.", "Many of these streets began as trading routes centuries ago, long before any modern city grew up around them. Merchants specializing in a single good — silk, spices, metalwork, paper — often clustered together on one street, since buyers found it easier to compare goods sold close by. Over time, some streets became known almost entirely for one craft, and that reputation, once earned, could last for generations even as the surrounding city changed dramatically around it .", "Tourism has reshaped many of these streets in the past few decades, sometimes gently and sometimes abruptly . Shops that once served local residents now cater mainly to visitors, selling souvenirs instead of daily necessities. Rents have risen sharply in some of the most photographed locations, pushing out small family businesses that could no longer afford the space their grandparents once rented cheaply. A few streets have become so associated with tourism that locals rarely shop there anymore, visiting mainly to eat at a favorite old stall.", "In response, some city governments and local communities have taken steps to protect what remains of a street's original character. A handful of streets now hold official heritage status, which limits how much a building's outer appearance can be altered, even if the shop inside changes completely. Community groups in a few cities have also pushed successfully for rules requiring new businesses to keep certain design elements, such as traditional shop signs or window shapes, even when the goods being sold have nothing to do with the street's original trade.", "None of these efforts fully resolves the underlying tension between commerce and memory. A street can keep its old signs and still lose its old rhythm, its old customers, and its old smells. Yet a street frozen entirely in the past would likely lose the very thing that made it lively in the first place — the constant , practical business of buying and selling. What survives, in most cases, is neither fully preserved nor fully changed, but something adapted, imperfectly, from both."], questions: [{ q: "According to the passage, why did merchants selling a single good often cluster on the same street?", options: ["because city officials required merchants to organize by trade", "because guild leaders assigned each merchant a fixed location", "because buyers found it easier to compare goods sold close together", "because rent was cheaper on streets with fewer separate businesses"], answer: 2 }, { q: "What is the passage mainly about?", options: ["The ongoing tension between commercial change and memory on Asia's old streets.", "The specific heritage rules some cities have adopted for old streets.", "How tourism has permanently destroyed the character of Asia's old streets.", "How every old trading street in Asia eventually disappears entirely."], answer: 0 }, { q: "The word \"abruptly\" in paragraph 3 is closest in meaning to _______.", options: ["slowly", "quietly", "annually", "suddenly"], answer: 3 }, { q: "According to the passage, what happened to rents in some of the most photographed locations?", options: ["They fell sharply, attracting new small family businesses.", "They rose sharply, pushing out small family businesses.", "They stayed the same, protecting long-term family businesses.", "They rose gradually, allowing family businesses time to adapt."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a way communities have protected a street's character?", options: ["They required new shops to sell only traditional local goods.", "They granted official heritage status limiting exterior building changes.", "They required businesses to keep traditional shop signs in place.", "They required businesses to preserve certain traditional window shapes."], answer: 0 }, { q: "The word \"it\" in paragraph 2 refers to _______.", options: ["the surrounding city", "the modern city", "the street", "that reputation"], answer: 2 }, { q: "According to the passage, what does the passage suggest would happen if a street were frozen entirely in the past?", options: ["It would likely gain new tourism revenue from historical preservation.", "It would likely lose the practical trading activity that made it lively.", "It would likely regain the exact customers it had a century ago.", "It would likely qualify automatically for official heritage status citywide."], answer: 1 }, { q: "What can be inferred about streets that have become closely associated with tourism?", options: ["Local residents have completely stopped visiting these streets for any reason.", "Rising rents occurred mainly because local residents had already stopped shopping there.", "Rents have risen sharply in some of the most heavily photographed locations.", "Local residents may now visit mainly for nostalgic reasons rather than daily shopping."], answer: 3 }, { q: "The word \"constant\" in paragraph 5 is closest in meaning to _______.", options: ["continuous", "occasional", "profitable", "historic"], answer: 0 }, { q: "What is the author's overall attitude toward the changes happening on these historic streets?", options: ["Strongly critical, blaming tourism entirely for destroying these streets forever.", "Purely nostalgic, wishing every street could return to its original state.", "Balanced, acknowledging both real loss and the practical need for adaptation.", "Entirely optimistic, expressing no concern about what these streets have lost."], answer: 2 }] },
    { title: "The Uneven Maturing of Southeast Asia's Online Retail", paragraphs: ["Southeast Asia's online retail sector is often described in single, sweeping terms — as one of the world's fastest-growing e-commerce regions, a story of smartphones and rising incomes converging into a single consumer boom. That description, while not inaccurate at the regional level, flattens enormous variation beneath it, since the region comprises economies at markedly different stages of digital and physical infrastructure development, and a platform succeeding in one country's dense urban core may face an entirely different set of constraints two borders away.", "Delivery infrastructure illustrates this unevenness clearly. In metropolitan Jakarta, Bangkok, or Manila, same-day delivery has become a realistic expectation for many consumers, supported by dense road networks and a large pool of motorbike couriers. Beyond these urban centers, however, delivery times can stretch to several days or longer, not because demand is absent but because the underlying road and warehousing infrastructure required for fast fulfillment was never built with rural or secondary-city delivery in mind.", "Payment behavior diverges just as sharply. In several markets, cash-on-delivery remains the dominant payment method even for platforms actively promoting digital wallets, reflecting persistent gaps in banking access and, in some cases, lingering distrust of prepaying for goods not yet received. Elsewhere, digital payment adoption has advanced rapidly, driven less by consumer preference alone than by aggressive subsidization from payment providers eager to capture transaction data and establish early market dominance.", "Regulatory frameworks add a further layer of fragmentation . Cross-border e-commerce rules, customs procedures, and tax treatment of digital transactions differ substantially from one country to the next, and harmonization efforts, while periodically announced, have progressed slowly relative to the pace of commercial activity they are meant to govern. A seller operating profitably across three countries may find that identical products require three separate compliance strategies, a burden that falls disproportionately on smaller merchants lacking dedicated legal resources.", "Beneath this infrastructural and regulatory unevenness sits a period of aggressive platform competition, much of it financed by investor capital rather than operating revenue. Deep discounts and free-shipping promotions, sustained well beyond what unit economics alone would justify, have shaped consumer expectations in ways that may prove difficult to reverse once subsidies eventually taper — a pattern some analysts argue is now entering a correction phase, as investor patience for unprofitable growth narrows across the broader technology sector.", "This competitive intensity has downstream labor consequences rarely covered with the same attention as consumer-facing growth statistics. Delivery work has absorbed a substantial share of newly informal employment across the region, offering flexible entry but comparatively little of the stability or benefit structure associated with formal employment. Whether this arrangement represents a durable feature of the sector's labor model or a transitional phase preceding stronger regulation remains, at this stage, genuinely unresolved.", "None of this unevenness necessarily contradicts the broader growth narrative; regional transaction volumes have, by most measures, continued to expand. What the unevenness does complicate is any assumption that the region is moving along a single, converging trajectory toward a uniform digital retail market. A more accurate account treats Southeast Asian e-commerce not as one maturing market but as several distinct markets maturing along different timelines, shaped by infrastructure, regulation, and capital availability that vary as much within the region as they do between it and the rest of the world."], questions: [{ q: "According to the passage, why can delivery times stretch to several days outside major urban centers?", options: ["because road and warehousing infrastructure was never built for rural delivery", "because demand outside major cities is too low to justify investment", "because platforms deliberately restrict service outside major urban centers", "because motorbike couriers refuse to travel beyond city limits"], answer: 0 }, { q: "What is the passage mainly about?", options: ["The specific reasons cash-on-delivery remains common in some Southeast Asian markets.", "Why every Southeast Asian country now shares an identical digital retail market.", "The significant unevenness underlying Southeast Asia's overall e-commerce growth narrative.", "How investor-funded price wars became the defining story of the region's retail sector."], answer: 2 }, { q: "The word \"fragmentation\" in paragraph 4 is closest in meaning to _______.", options: ["unity", "efficiency", "profitability", "division"], answer: 3 }, { q: "What do delivery infrastructure and payment behavior have in common as challenges for Southeast Asian e-commerce?", options: ["Both were resolved once digital wallets became available regionally.", "Both reveal significant variation rather than a single, uniform regional pattern.", "Both are primarily caused by government regulation restricting market entry.", "Both improved mainly because of subsidies from international investors."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a source of unevenness in Southeast Asia's online retail sector?", options: ["Differences in the language used in marketing content across markets.", "Divergence in payment methods used across different markets.", "Fragmentation in regulatory frameworks governing cross-border commerce.", "Gaps in delivery infrastructure between urban and rural areas."], answer: 0 }, { q: "The word \"it\" in paragraph 7 refers to _______.", options: ["the rest of the world", "the region", "infrastructure and regulation", "capital availability"], answer: 1 }, { q: "What connects aggressive platform competition and the growth of informal delivery labor?", options: ["Informal delivery labor caused platforms to abandon investor-funded discounting entirely.", "Government regulation directly created both platform competition and informal labor growth.", "Competitive pressure to sustain low prices relied partly on flexible, unstable labor.", "Aggressive competition eliminated the need for any delivery labor at all."], answer: 2 }, { q: "What can be inferred about the future of deep discounts and free-shipping promotions in the region?", options: ["These promotions will disappear completely and permanently within the next year.", "Investor patience narrowed mainly because consumer expectations became too difficult to reverse.", "Some analysts argue the sector is now entering a correction phase.", "Consumer expectations shaped by subsidies may be difficult to sustain once funding decreases."], answer: 3 }, { q: "The word \"durable\" in paragraph 6 is closest in meaning to _______.", options: ["lasting", "temporary", "profitable", "informal"], answer: 0 }, { q: "What is the author's overall attitude toward the narrative that Southeast Asia is one uniformly maturing e-commerce market?", options: ["Fully supportive, agreeing the region functions as one converging market.", "Skeptical, treating the region as several distinct markets maturing at different rates.", "Dismissive, denying that any meaningful growth has occurred in the region.", "Neutral, offering no assessment of whether the growth narrative is accurate."], answer: 1 }] },
    { title: "Rethinking the Bystander: What Drives Ordinary People to Intervene", paragraphs: ["For decades, the dominant explanation for why witnesses to an emergency often fail to help has centered on a single, memorable idea: the presence of other people inhibits individual action, an effect popularized after press coverage of a 1964 murder in New York suggested, controversially, that dozens of witnesses had watched without intervening. The story that emerged from that case, however, was later shown to be considerably less clear-cut than initial reporting implied, and the psychological theory it inspired has, over the following decades, undergone significant revision.", "The original theoretical account, developed through a series of laboratory experiments in the late 1960s, proposed two related mechanisms. Diffusion of responsibility suggested that each bystander feels less personally obligated to act as the number of witnesses increases, since responsibility is implicitly divided among everyone present. Pluralistic ignorance, a related but distinct mechanism, proposed that bystanders look to each other's outward calm for cues about whether a situation is truly an emergency, and a crowd of individually uncertain people can collectively appear falsely composed , delaying everyone's response at once.", "Recent research, drawing on an unlikely data source — security camera footage of real, naturally occurring public conflicts — has complicated this picture considerably. Analyses of hundreds of recorded incidents across several countries found that some form of intervention occurred in the substantial majority of cases, far more often than laboratory-based bystander studies would predict. This finding does not overturn the original theory outright, but it does suggest that inhibition, where it occurs, may be more conditional and situation-dependent than the classic account implies.", "Several factors appear to shape whether a given bystander intervenes. Familiarity among witnesses reduces inhibition considerably; strangers surrounded by other strangers hesitate more than individuals embedded within a group of people they already know, since the diffusion of responsibility that troubled Latané and Darley's original subjects seems to weaken substantially once social bonds, even loose ones, connect the people present. Perceived severity matters as well — witnesses appear far more willing to intervene once a conflict crosses a threshold read as physically dangerous, even when doing so involves genuine personal risk.", "Physical and psychological proximity to the victim further modulate the likelihood of action, though not always in the direction intuition might suggest. Closer physical proximity increases the pressure to act, but it does not guarantee intervention if the bystander interprets the situation as a private matter rather than a genuine emergency — a distinction that camera footage analysis suggests bystanders make quickly, sometimes within seconds, based on cues as subtle as tone of voice or body posture between the parties involved.", "None of this evidence resolves the underlying theoretical debate entirely, and researchers caution against treating footage-based intervention rates as a simple refutation of decades of laboratory findings; the two research traditions examine somewhat different phenomena under different conditions, and reconciling them fully remains an active area of inquiry. What does seem increasingly clear, however, is that the bystander effect, as popularly understood, describes a real but narrower phenomenon than the original framing suggested — one shaped as much by group familiarity, perceived severity, and situational interpretation as by the mere number of people present."], questions: [{ q: "According to the passage, what did the mechanism of pluralistic ignorance propose?", options: ["bystanders divide the perceived responsibility equally among everyone present", "bystanders look to others' outward calm for emergency cues", "bystanders assume someone with authority will intervene first", "bystanders wait for a clear signal directly from the victim"], answer: 1 }, { q: "What is the passage mainly about?", options: ["The specific camera-footage methods used in recent bystander research.", "How camera footage completely disproved the original bystander effect theory.", "Why bystanders in every country respond identically to public emergencies.", "How research has revised the classic bystander-effect account."], answer: 3 }, { q: "The word \"modulate\" in paragraph 5 is closest in meaning to _______.", options: ["influence", "prevent", "guarantee", "measure"], answer: 0 }, { q: "How does recent camera-footage research relate to the original laboratory-based theory?", options: ["It completely overturns the original theory, proving diffusion never occurs.", "It was conducted using the same laboratory methods as the original studies.", "It complicates but does not fully overturn the original account of inhibition.", "It confirms every prediction the original laboratory-based theory originally made."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a factor shaping whether a bystander intervenes?", options: ["The degree of familiarity among the witnesses present.", "The bystander's own prior training in administering first aid.", "How physically or psychologically close the bystander is to the victim.", "Whether the conflict is perceived as sufficiently severe or dangerous."], answer: 1 }, { q: "The word \"it\" in paragraph 5 refers to _______.", options: ["the bystander effect", "psychological proximity", "the victim's behavior", "closer physical proximity"], answer: 3 }, { q: "What can be inferred about the relationship between the classic bystander-effect theory and the newer camera-footage findings?", options: ["The two research traditions may examine different aspects of a genuinely complex phenomenon.", "The two research traditions have already been fully reconciled by current researchers.", "Camera footage was developed specifically because researchers requested better laboratory evidence.", "Some form of intervention occurred in the majority of recorded incidents."], answer: 0 }, { q: "According to the passage, how does familiarity among witnesses affect the likelihood of intervention?", options: ["It increases inhibition considerably, making bystanders less likely to act.", "It has no measurable effect on whether bystanders intervene at all.", "It reduces inhibition considerably, making bystanders more likely to act.", "It matters only when the conflict is perceived as physically dangerous."], answer: 2 }, { q: "The word \"composed\" in paragraph 2 is closest in meaning to _______.", options: ["confused", "calm", "responsible", "informed"], answer: 1 }, { q: "What is the author's overall attitude toward the classic bystander-effect narrative as popularly understood?", options: ["Fully dismissive, arguing the bystander effect has never been observed in any study.", "Fully accepting, arguing the classic narrative requires no further qualification at all.", "Uncertain, offering no assessment of whether the narrative holds any validity.", "Measured, treating it as real but narrower than the popular narrative suggests."], answer: 3 }] },
    { title: "Beyond Charisma: Self-Examination as a Leadership Discipline", paragraphs: ["Leadership development programs have long gravitated toward charisma as though it were the discipline's foundational variable — the trait from which persuasive vision, follower loyalty, and organizational momentum are all presumed, more or less directly, to flow. Not only does this emphasis persist despite decades of mixed empirical support, but it has arguably deepened, as media coverage of prominent executives continues to attribute organizational outcomes overwhelmingly to individual personality rather than to the less visible, more distributed mechanisms that organizational research increasingly implicates instead.", "That charisma correlates with certain short-term outcomes — heightened follower enthusiasm, more favorable performance ratings in the months immediately following a leadership transition — is not seriously disputed. What is disputed, increasingly, is whether these short-term correlations translate into anything resembling durable organizational health, since several longitudinal studies tracking leadership cohorts over a decade or more have found charisma's predictive power for outcomes such as employee retention and long-term financial performance to be considerably weaker than its predictive power for immediate follower impressions.", "A quieter body of leadership research has, over roughly the same period, converged on a different candidate variable: self-examination, understood not as generic introspection but as a structured, recurring practice of soliciting disconfirming feedback and revising one's own operating assumptions accordingly. While charisma tends to be treated in the literature as comparatively fixed — a trait one either possesses in meaningful degree or does not — self-examination is characterized, across nearly every study reviewed here, as trainable , and its trainability may be precisely what accounts for its stronger association with sustained rather than merely initial organizational performance.", "The mechanism proposed to explain this association is not, as intuition might suggest, that self-examining leaders simply make fewer errors. Rather, the proposed mechanism concerns error correction speed: leaders who habitually solicit and act on disconfirming feedback appear to identify and reverse flawed strategic assumptions considerably faster than leaders who do not, a difference that compounds meaningfully across years even when the two groups' initial error rates are statistically indistinguishable. Whether this compounding effect fully accounts for the long-term performance gap observed, or merely contributes to it alongside other, less-studied variables, remains a question the current evidence cannot resolve with confidence.", "Institutional obstacles to cultivating this discipline are, however, considerable, and arguably more entrenched than obstacles to cultivating charisma. Organizational hierarchies routinely insulate senior leaders from precisely the kind of disconfirming feedback self-examination requires, not through any deliberate conspiracy but through an accumulation of smaller incentive distortions — subordinates calibrating candor to perceived risk, boards rewarding confident narrative over qualified uncertainty, media coverage rewarding decisiveness over visible reconsideration — each individually minor, collectively substantial.", "Some organizations have attempted structural interventions intended to counteract this insulation: mandatory 360-degree review processes, external advisory boards explicitly tasked with challenging leadership assumptions, rotating internal dissent roles modeled loosely on the historical devil's advocate. Evidence on these interventions' effectiveness is, at present, decidedly mixed; several studies suggest their impact depends less on the intervention's formal design than on whether senior leadership visibly treats disconfirming feedback as valuable rather than merely tolerated, a distinction subordinates appear to detect quickly and to calibrate their own candor against accordingly.", "None of this amounts to a wholesale dismissal of charisma's relevance to leadership, and the argument advanced here should not be mistaken for one. Charisma retains clear value in specific circumstances — crisis communication, rapid mobilization of a workforce around an urgent priority — where its short-term advantages are neither disputed nor, on the evidence available, easily substituted for. The more defensible position is narrower: that charisma and self-examination address different organizational needs operating on different time horizons, and that leadership development programs weighted overwhelmingly toward the former may be optimizing for exactly the outcomes least correlated with an organization's long-term health."], questions: [{ q: "According to the passage, what do longitudinal studies suggest about charisma's predictive power?", options: ["It predicts long-term financial performance more strongly than immediate follower impressions.", "It predicts almost nothing measurable about either short-term or long-term outcomes.", "It predicts immediate follower impressions more strongly than durable outcomes like retention.", "It predicts long-term outcomes moderately well, though less consistently than short-term ones."], answer: 2 }, { q: "What is the passage mainly about?", options: ["Why self-examination may be a more durable, harder-to-institutionalize leadership discipline than charisma.", "The specific mechanism by which self-examination speeds error correction in leaders.", "How charisma has been proven to outperform self-examination on every leadership outcome.", "Why all organizational leadership programs should abandon charisma entirely and immediately."], answer: 0 }, { q: "The word \"insulate\" in paragraph 5 is closest in meaning to _______.", options: ["expose", "reward", "train", "shield"], answer: 3 }, { q: "Why might self-examination's trainability help explain its stronger association with long-term organizational performance?", options: ["Because trainability guarantees leaders will make no strategic errors at all.", "Because it lets leaders correct flawed assumptions faster than a fixed trait would.", "Because trainability was shown to eliminate the need for disconfirming feedback entirely.", "Because trainable leaders start with a lower initial error rate than others."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a factor insulating senior leaders from disconfirming feedback?", options: ["Subordinates calibrating their candor to perceived professional risk.", "Boards rewarding confident narrative over qualified uncertainty.", "A formal policy explicitly banning critical feedback from subordinates.", "Media coverage rewarding decisiveness over visible reconsideration."], answer: 2 }, { q: "The word \"its\" in paragraph 7 refers to _______.", options: ["charisma", "crisis communication", "self-examination", "leadership development"], answer: 0 }, { q: "What can be inferred about the effectiveness of structural interventions like 360-degree reviews?", options: ["These interventions have been proven consistently effective across every organization studied.", "Subordinates' candor levels caused organizations to adopt these interventions in the first place.", "Evidence on these interventions' effectiveness is, at present, decidedly mixed.", "Their effectiveness may depend more on genuine buy-in than formal design."], answer: 3 }, { q: "According to the passage, in which circumstance does the passage say charisma retains clear value?", options: ["in circumstances involving routine daily management of established teams", "in circumstances involving crisis communication and rapid workforce mobilization", "in circumstances involving long-term strategic planning across multiple fiscal years", "in circumstances involving formal succession planning for senior leadership roles"], answer: 1 }, { q: "The word \"entrenched\" in paragraph 5 is closest in meaning to _______.", options: ["temporary", "visible", "established", "measurable"], answer: 2 }, { q: "What is the author's overall stance toward the relative value of charisma and self-examination in leadership?", options: ["Measured, arguing self-examination deserves more attention without fully dismissing charisma's value.", "Fully dismissive of charisma, arguing it has no legitimate role in leadership at all.", "Fully dismissive of self-examination, treating it as an impractical academic ideal.", "Uncertain, offering no clear position on the relative value of either quality."], answer: 0 }] },
  ] },
  { id: "rd-166", num: 166, title: "Đề 166", timeMin: 60, parts: [
    { title: "More Than Green Space: What City Parks Actually Do for a Neighborhood", paragraphs: ["When people think about a city park, they usually picture grass, trees, and maybe a playground where children can run around. That picture is not wrong, but it leaves out most of what a well-used park actually does for the people who live near it. A good park is not just empty green space between buildings — it is a place where neighbors who would otherwise never speak to each other end up sharing a bench, watching the same football game, or waiting for the same food truck.", "One of the clearest benefits of a park is simply that it gives people a free place to be active. Not everyone can afford a gym membership or a home with a garden, so a park with open grass, walking paths, and outdoor equipment often becomes the only realistic place for regular exercise. Doctors and health researchers have pointed out for years that people who live within a short walk of a park tend to exercise more often than people who do not, even when nothing else about their daily routine is different. A ten-minute walk to a park is usually enough to make a real difference in how often someone chooses to move their body.", "Parks also matter for mental health, in ways that are easy to underestimate. Spending even twenty minutes among trees and grass has been shown to lower stress levels for many people, and a short walk through a quiet park can noticeably improve someone's mood after a difficult day at work. This effect appears to be strongest for people who live in crowded, noisy parts of a city, where a park offers one of the only quiet outdoor spaces available to them .", "Beyond exercise and mental health, parks bring neighbors together in ways that few other public spaces manage to do. Unlike a shopping mall or a cinema, a park does not require anyone to spend money to belong there. Families having a picnic, teenagers playing basketball, and older residents playing chess at a stone table can all use the same park at the same time without getting in each other's way. Over months and years, these small, repeated interactions help neighbors recognize each other and feel more comfortable in their own neighborhood.", "Of course, not every park delivers these benefits equally. A park that is poorly maintained , badly lit, or seen as unsafe at night will keep people away no matter how much green space it contains, and some neighborhoods still lack easy access to any decent park at all. Cities that want their residents to be healthier and more connected to each other need to treat park maintenance and safety as seriously as they treat the parks themselves, since a park that people are afraid to use cannot deliver any of these benefits in practice."], questions: [{ q: "According to the passage, how long a walk to a park is usually enough to make a real difference in how often someone exercises?", options: ["a thirty-minute walk", "a ten-minute walk", "a two-hour walk", "a one-minute walk"], answer: 1 }, { q: "According to the passage, roughly how much time spent among trees and grass has been shown to lower stress levels for many people?", options: ["two hours", "five minutes", "a full day", "twenty minutes"], answer: 3 }, { q: "The word \"realistic\" in paragraph 2 is closest in meaning to _______.", options: ["imaginary", "practical", "temporary", "expensive"], answer: 1 }, { q: "What is the main idea of the passage?", options: ["Only wealthy neighborhoods can afford to build and maintain good parks.", "Good parks provide physical, mental, and social benefits to local residents.", "Parks are mainly useful as decoration between buildings in a city.", "Shopping malls and cinemas bring neighbors together better than parks do."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as an example of people using a park at the same time?", options: ["teenagers playing basketball", "older residents playing chess", "office workers holding a business meeting", "families having a picnic"], answer: 2 }, { q: "The word \"them\" in paragraph 3 refers to _______.", options: ["trees and grass", "doctors and health researchers", "quiet outdoor spaces", "people who live in crowded"], answer: 3 }, { q: "According to the passage, what happens to a park that is poorly maintained, badly lit, or seen as unsafe at night?", options: ["It automatically becomes more popular because it feels more private.", "It is quickly repaired by the city before residents notice any problem.", "It attracts more visitors looking for a quiet place to relax.", "It keeps people away no matter how much green space it contains."], answer: 3 }, { q: "The word \"maintained\" in paragraph 5 is closest in meaning to _______.", options: ["kept in good condition", "rarely visited", "privately owned", "built recently"], answer: 0 }, { q: "What can be inferred from the passage about a neighborhood that lacks easy access to any decent park?", options: ["Its residents may lose out on key health and community benefits.", "It will have no effect at all on how connected residents feel to their neighbors.", "Its residents will automatically build their own private parks instead.", "Its residents will exercise exactly as much as residents who live near a good park."], answer: 0 }, { q: "What is the author's overall attitude toward the value of city parks?", options: ["Dismissive, viewing parks as a minor and largely unnecessary part of city life.", "Genuinely appreciative, while cautioning that a park's benefits depend on it being safe and well kept.", "Uncritically enthusiastic, suggesting every park delivers the same benefits regardless of condition.", "Neutral to the point of expressing no real opinion about parks at all."], answer: 1 }] },
    { title: "Engineering Wonder: The Hidden Systems Behind a Disneyland Day", paragraphs: ["Visitors who spend a day at Disneyland rarely think about the invisible systems keeping the experience running smoothly, yet a single day at the park depends on a level of logistical planning that would not look out of place in an airport control tower. Behind every parade, every ride restart, and every seemingly spontaneous character appearance sits a tightly coordinated operation designed specifically so that guests never notice it is there.", "Crowd flow management is arguably the least visible but most consequential of these systems. Park designers position attractions, food stands, and pathways so that visitor movement is subtly guided without anyone feeling directed, using techniques such as gently curving walkways that obscure how far a queue actually stretches and staggered ride opening times that prevent every attraction from filling up at once. A queue that curves out of sight can feel shorter than a straight one of identical length, which is precisely why so few queues at the park run in a straight line for any real distance.", "Beneath the visible park lies a network of utility tunnels, sometimes called the \"utilidors,\" through which staff move costumes, supplies, and even themselves between different themed areas without crossing through guest-facing spaces. This tunnel system , most extensively developed at the Florida property, allows a costumed character to disappear near one attraction and reappear minutes later on the opposite side of the park, reinforcing the illusion that each themed land exists as its own self-contained world untouched by the mechanics of the other.", "Ride maintenance follows a philosophy that differs sharply from ordinary industrial upkeep: rather than waiting for a breakdown, engineers rely on predictive schedules that replace parts well before they show any sign of failure, since a mid-day shutdown does more damage to visitor experience than the cost of an early replacement ever would. Some attractions are taken fully offline overnight for inspection routines that a typical guest would never notice, precisely because the goal is for a ride to appear as though it has always simply worked, with no visible history of adjustment or repair.", "Weather planning receives comparably serious attention, though it rarely gets acknowledged as engineering at all. Drainage systems beneath walkways are designed to clear sudden downpours within minutes rather than hours, and covered waiting areas are positioned along routes likely to see the heaviest rain-driven foot traffic, allowing the park to keep functioning through weather that might otherwise close an ordinary outdoor venue for the rest of the day.", "Staff training compounds all of these physical systems with a behavioral one. Employees, referred to internally as \"cast members,\" are trained not merely in customer service but in a form of continuous, subtle improvisation — maintaining character consistency, redirecting guests without appearing to give directions, and defusing minor complaints before they escalate into visible disruptions that other guests might notice and imitate.", "Taken together, these systems reveal a park whose most impressive engineering achievement may not be any single ride but the surrounding infrastructure engineered specifically to remain unseen, allowing the fantasy on the surface to function as though no infrastructure exists at all."], questions: [{ q: "According to the passage, why do so few queues at the park run in a straight line for any real distance?", options: ["Straight queues are more expensive to build than curved ones.", "A curved queue feels shorter, making wait times seem more manageable.", "Curved queues allow more attractions to be built in the same amount of space.", "Straight queues are required by local safety regulations to include seating."], answer: 1 }, { q: "What is the main idea of the passage?", options: ["Cast members are trained primarily to perform in parades rather than to manage guest experience.", "Disneyland's weather planning has made it immune to any operational disruption.", "Disneyland's rides are the park's single most impressive engineering feat.", "Disneyland relies on seamless, invisible systems to run smoothly."], answer: 3 }, { q: "The word \"staggered\" in paragraph 2 is closest in meaning to _______.", options: ["spaced out over time", "cancelled entirely", "randomly selected", "extended indefinitely"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as part of the park's hidden operational systems?", options: ["drainage systems designed to clear sudden downpours quickly", "predictive ride maintenance schedules", "a centralized ticket-pricing algorithm adjusted hourly", "a network of underground utility tunnels"], answer: 2 }, { q: "According to the passage, what is the underlying philosophy behind the park's approach to ride maintenance?", options: ["Rides are only inspected once a year regardless of how often they are used.", "Maintenance is performed only after a visible malfunction has already occurred.", "Parts are replaced on predictive schedules before any failure occurs.", "Guests are informed in advance whenever a ride undergoes maintenance."], answer: 2 }, { q: "The phrase \"This tunnel system\" in paragraph 3 refers to _______.", options: ["the network of utility tunnels known as the \"utilidors\"", "the predictive ride maintenance schedule", "the drainage system beneath walkways", "the covered waiting areas near ride entrances"], answer: 0 }, { q: "The word \"defusing\" in paragraph 6 is closest in meaning to _______.", options: ["deliberately ignoring", "calming down", "publicly recording", "escalating further"], answer: 1 }, { q: "According to the passage, how are drainage systems beneath walkways designed to respond to sudden downpours?", options: ["They are designed to clear sudden downpours within minutes rather than hours.", "They are designed to slowly drain the park over the course of several hours.", "They redirect rainwater exclusively toward the underground utility tunnels.", "They are only activated when park attendance drops below a certain level."], answer: 0 }, { q: "What can be inferred from the passage about the overall goal shared by crowd flow design, the tunnel system, ride maintenance, and staff training?", options: ["These systems were introduced mainly in response to guest complaints about ride wait times.", "They all aim to keep the park's operations hidden from visitors.", "Each system exists primarily to reduce the park's overall staffing costs.", "Each system is designed independently with no shared purpose across departments."], answer: 1 }, { q: "What is the author's overall purpose in this passage?", options: ["To explain the hidden engineering behind a smooth Disneyland visit.", "To criticize Disneyland for hiding its maintenance costs from the public.", "To argue that Disneyland's weather planning is its most historically significant achievement.", "To compare Disneyland's tunnel system unfavorably with that of other theme parks."], answer: 0 }] },
    { title: "The Limits of Self-Improvement: What the Research Actually Supports", paragraphs: ["Bookshops now devote entire sections to self-improvement, and productivity apps promise measurable transformation within weeks, yet psychologists who study behavior change increasingly warn that the industry's confident tone rarely matches the tentative, conditional findings underlying it. A closer look at the research suggests that most durable personal change owes less to willpower or motivation than to a handful of structural conditions that popular advice frequently overlooks entirely.", "Carol Dweck's work on mindset is perhaps the most widely cited concept in this space, and it has been simplified, in translation from laboratory to bestseller, almost beyond recognition. The original studies distinguished between believing ability is fixed versus believing it can be developed through effort, and found modest but real effects on how students responded to academic setbacks specifically. What later popularizers added — the implication that any failure can be transformed into success through sheer belief — was never part of the original claim, and subsequent replication attempts have found the effect to be considerably smaller, and far more dependent on context, than early accounts suggested.", "A similar gap between folk wisdom and evidence appears around habit formation. The frequently repeated claim that a new habit takes twenty-one days to form traces back to a 1960s plastic surgeon's informal observations about patients adjusting to their new appearance, not to any controlled study of habit acquisition; more rigorous recent research places the true figure much higher on average, while also showing enormous variation depending on the habit's complexity and how consistently it is practiced. Because that entrenched twenty-one-day figure sounds precise and actionable, it has persisted in popular advice for decades despite never having been empirically established in the first place.", "Goal-setting research offers a more consistently supported picture, though even here the popular version oversimplifies. Merely stating an intention — \"I will exercise more\" — predicts behavior change poorly. What predicts it considerably better, across dozens of studies, is what researchers call an implementation intention: a specific if-then plan linking a concrete situational cue to a concrete action, such as committing to a particular time, place, and trigger for the behavior in advance. The gap between these two approaches is not a matter of degree but of a genuinely different psychological mechanism, since implementation intentions appear to work by automating the decision itself rather than relying on motivation at the moment of action.", "Self-discipline, meanwhile, is often framed in popular writing as something to be maximized without limit, yet a growing body of research complicates this picture considerably. Studies comparing self-critical and self-compassionate approaches to failure have found that excessive self-criticism after a setback tends to reduce, rather than increase, the likelihood of trying again, apparently because it heightens the emotional cost of failure without offering any corresponding motivational benefit. Self-compassion, by contrast — treating one's own failures with the same patience one might extend to a friend — has been linked in several studies to greater persistence, though researchers caution that this finding does not extend to a license for indefinite self-indulgence.", "What much of this research converges on, perhaps counterintuitively, is that individual willpower explains far less of sustained behavior change than structural and environmental factors do. Removing friction from a desired behavior — placing running shoes by the door, for instance — and adding friction to an undesired one tends to outperform purely motivational strategies in study after study, which may suggest that the self-improvement industry's heavy emphasis on mindset and discipline reflects what sells more easily than what the evidence actually supports.", "None of this means personal effort is irrelevant, only that its role is narrower and more conditional than popular narratives suggest. The consistent thread across mindset, habit, goal-setting, and self-compassion research is not that trying harder fails, but that trying in a psychologically better-designed way succeeds far more reliably than trying with more intensity alone."], questions: [{ q: "According to the passage, what did Carol Dweck's original studies actually find about mindset?", options: ["Modest, context-specific effects on how students handled academic setbacks.", "That believing ability is fixed produces better academic outcomes than believing it can be developed.", "That mindset has no measurable effect on how people respond to setbacks of any kind.", "That any failure could be transformed into success through sheer belief in one's abilities."], answer: 0 }, { q: "According to the passage, which of the following is NOT presented as a factor genuinely supported by behavior-change research?", options: ["self-compassion following a setback, within reasonable limits", "maximizing self-criticism after failure to sharpen future motivation", "implementation intentions that link a specific cue to a specific action", "removing environmental friction from a desired behavior"], answer: 1 }, { q: "The word \"entrenched\" in paragraph 3 is closest in meaning to _______.", options: ["firmly established", "widely disputed", "loosely defined", "recently discovered"], answer: 0 }, { q: "According to the passage, where does the popular claim that habits take twenty-one days to form actually originate?", options: ["A large-scale controlled study of habit acquisition conducted in the 1960s.", "Informal observations by a plastic surgeon about patients adjusting to a new appearance.", "A survey of self-improvement authors about their own personal experience.", "Recent research measuring the average time needed to form a new habit."], answer: 1 }, { q: "The phrase \"The gap between these two approaches\" in paragraph 4 refers to the difference between _______.", options: ["removing friction and adding friction to a behavior", "merely stating an intention and forming a specific implementation intention", "self-criticism and self-compassion after a setback", "fixed mindset and growth mindset"], answer: 1 }, { q: "What is the main idea of the passage?", options: ["Self-compassion is scientifically proven to be more effective than any other behavior-change strategy in all situations.", "Carol Dweck's mindset research has been fully discredited by later replication studies.", "Personal effort is irrelevant to behavior change, since only environmental design matters.", "Popular advice oversimplifies research; lasting change relies on structural design over willpower."], answer: 3 }, { q: "What can be inferred about how popular self-improvement writing tends to treat academic research?", options: ["It exaggerates modest research findings into overly dramatic claims.", "It tends to accurately reproduce the exact statistical findings of the original studies.", "It tends to ignore behavioral research entirely in favor of purely anecdotal advice.", "It tends to focus exclusively on habit-formation research while ignoring mindset research."], answer: 0 }, { q: "The word \"friction\" in paragraph 6 is closest in meaning to _______.", options: ["resistance or obstacles", "public criticism", "emotional attachment", "financial cost"], answer: 0 }, { q: "According to the passage, what tends to happen after excessive self-criticism following a setback?", options: ["It has no measurable effect on whether someone tries again.", "It works only for people who also practice self-compassion at the same time.", "It tends to reduce, rather than increase, the likelihood of trying again.", "It reliably increases the likelihood of trying again by heightening motivation."], answer: 2 }, { q: "What is the author's overall attitude toward the self-improvement industry, as expressed across the passage?", options: ["Neutral, offering no evaluation of the gap between research and popular claims.", "Uncritically supportive of popular self-improvement advice as currently presented.", "Entirely dismissive, viewing all self-improvement research as unfounded.", "Skeptical of its hype, yet open to valid findings."], answer: 3 }] },
    { title: "Invisible in Plain Sight: Rethinking How Schools Identify Student Homelessness", paragraphs: ["Not only does student homelessness resist easy counting, but the very term may itself mislead policymakers into imagining a narrower problem than actually exists, since the population it describes rarely matches the image of a family sleeping outdoors that the word most readily evokes. The overwhelming majority of students affected are, at any given time, staying temporarily with relatives or family friends — an arrangement researchers term \"doubling up\" — a status that satisfies most legal definitions of homelessness while looking, to teachers and classmates alike, entirely unremarkable from the outside.", "This near-total invisibility complicates every stage of the policy response, beginning with identification itself. Schools are generally required to ask enrollment questions designed to surface housing instability, yet families experiencing it frequently decline to disclose their situation, whether from fear of child-welfare intervention, a reluctance to be defined by the arrangement, or simply because the family does not consider their own circumstance to fit what the word \"homeless\" is assumed to mean. Because identification depends so heavily on voluntary disclosure, official counts are widely regarded among researchers as substantial undercounts, though the degree of undercounting is difficult to establish with precision and appears to vary considerably by district and by how enrollment questions are worded.", "Academic consequences, once a student is identified, tend to compound rather than remain isolated to a single domain. Frequent moves between temporary housing arrangements often force corresponding school changes, and each transfer tends to disrupt not only continuity of instruction but also the informal social relationships — a trusted teacher, a familiar peer group — that research increasingly treats as protective factors in their own right rather than as incidental comforts. [1] Attendance records for these students show elevated rates of both absence and tardiness, though researchers caution against attributing this straightforwardly to motivation, since transportation logistics from an unstable or distant temporary residence plausibly account for a meaningful share of the pattern. [2]", "Legal protections exist specifically to counter some of these disruptions, most notably provisions requiring that a student be allowed to remain enrolled at their original school even after a housing move, with transportation arranged accordingly, rather than being forced to transfer immediately to a new zoned school. [3] In practice, however, awareness of this right varies considerably among both families and school staff, and some districts report that transportation logistics alone can undermine the protection even where the legal right is technically honored on paper.", "Beyond attendance and continuity, homelessness appears to interact with academic performance in ways that are difficult to disentangle from co-occurring stressors. Standardized test scores for identified students trail those of stably housed peers by a margin that researchers describe as consistent but modest in size, which may suggest that housing instability functions as one compounding stressor among several rather than as a single overwhelming determinant of achievement on its own. [4]", "Some districts have experimented with designating a specific staff liaison responsible for connecting affected families with transportation, school supplies, and referrals to outside housing services, a role required in some form by federal guidance though implemented with considerable variation in staffing and funding across districts. Early evaluations of these liaison positions report improved attendance and identification rates in the districts that fund the role adequately, though researchers note that these evaluations rarely include a comparison group rigorous enough to rule out other simultaneous interventions.", "What emerges from this body of research is not a simple story of neglect but one of a support system straining against a population that is, by its very nature, difficult to see, count, and reach — a mismatch between the visibility that policy responses generally require and the invisibility that housing instability, for reasons both practical and psychological, tends to produce."], questions: [{ q: "According to the passage, why do official counts of student homelessness tend to be regarded as undercounts?", options: ["Because most affected families are unaware that they qualify for any legal protections at all.", "Because federal guidance explicitly prohibits schools from asking about housing status.", "Because counting relies on voluntary disclosure, which many families decline.", "Because standardized test scores are the only method schools use to identify affected students."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a reason families might decline to disclose housing instability?", options: ["not considering their situation to fit the assumed meaning of \"homeless\"", "reluctance to be defined by the arrangement", "fear of child-welfare intervention", "a belief that disclosure would automatically improve their standardized test scores"], answer: 3 }, { q: "The phrase \"doubling up\" in paragraph 1 is closest in meaning to _______.", options: ["enrolling simultaneously in two different schools", "living in an emergency shelter designed for families", "sleeping outdoors without any temporary housing", "staying temporarily with relatives or family friends"], answer: 3 }, { q: "What is the main idea of the passage?", options: ["Standardized test scores are the most reliable method for identifying homeless students.", "Student homelessness is primarily a problem of inadequate legal protection rather than one of identification.", "Liaison programs have been proven, through rigorous controlled studies, to fully resolve the identification problem.", "The invisible nature of student homelessness severely hinders support systems."], answer: 3 }, { q: "The phrase \"this right\" in paragraph 4 refers to _______.", options: ["the right to a designated staff liaison in every school district", "the right to receive free standardized test preparation", "the right to stay in one's original school with transportation provided", "the right to decline enrollment questions about housing status"], answer: 2 }, { q: "According to the passage, what do researchers caution against when interpreting elevated absence and tardiness rates among affected students?", options: ["Assuming that liaison programs are the sole cause of any attendance changes observed.", "Concluding that attendance records are entirely unrelated to housing instability.", "Blaming poor motivation alone when transportation obstacles play a key role.", "Assuming that absence rates are lower for these students than for stably housed peers."], answer: 2 }, { q: "What can be inferred about the relationship between legal protections and their real-world effect?", options: ["Legal protections apply only to families who have already been formally identified through standardized testing.", "Legal protections can exist on paper but still fail due to practical logistics.", "School staff are always fully aware of these protections, so implementation gaps do not occur.", "Legal protections have fully eliminated the academic disruptions caused by frequent school transfers."], answer: 1 }, { q: "The word \"disentangle\" in paragraph 5 is closest in meaning to _______.", options: ["permanently resolve", "statistically inflate", "publicly announce", "separate out"], answer: 3 }, { q: "What degree of certainty does the passage assign to the claim that housing instability alone determines academic achievement?", options: ["The passage takes no position on academic achievement of any kind.", "High certainty — the passage states this as a firmly established, direct cause of low achievement.", "Low certainty — it acts as one of several factors rather than the main cause.", "Complete certainty that housing instability has no relationship to achievement whatsoever."], answer: 2 }, { q: "What is the author's overall purpose in this passage?", options: ["To prove conclusively that standardized test score gaps are caused entirely by housing instability.", "To explain how the unseen nature of student homelessness undermines support efforts.", "To recommend that all students be required to disclose their housing status upon enrollment.", "To argue that liaison programs should be eliminated because they lack rigorous evaluation."], answer: 1 }] },
  ] },
];
